from typing import List
from collections import deque
class Solution:
    def countOfPairs(self, n: int, x: int, y: int) -> List[int]:
        adj = [[i - 1, i + 1] for i in range(n)]
        adj[0] = [1]
        adj[n - 1] = [n - 2]
        if x != y:
            adj[x - 1].append(y - 1)
            adj[y - 1].append(x - 1)
        res = [0] * n
        for s in range(n):
            dist = [-1] * n
            dist[s] = 0
            dq = deque([s])
            while dq:
                u = dq.popleft()
                for w in adj[u]:
                    if dist[w] == -1:
                        dist[w] = dist[u] + 1
                        res[dist[w]] += 1
                        dq.append(w)
        return res

