class Solution {
public:
    vector<int> countOfPairs(int n, int x, int y) {
        vector<vector<int>> adj(n);
        for (int i = 0; i < n; ++i) {
            if (i > 0) adj[i].push_back(i - 1);
            if (i + 1 < n) adj[i].push_back(i + 1);
        }
        if (x != y) { adj[x-1].push_back(y-1); adj[y-1].push_back(x-1); }
        vector<int> res(n, 0);
        for (int s = 0; s < n; ++s) {
            vector<int> dist(n, -1);
            dist[s] = 0;
            queue<int> q; q.push(s);
            while (!q.empty()) {
                int u = q.front(); q.pop();
                for (int w : adj[u]) if (dist[w] == -1) {
                    dist[w] = dist[u] + 1;
                    ++res[dist[w]];
                    q.push(w);
                }
            }
        }
        return res;
    }
};

