class Solution {
    public int[] countOfPairs(int n, int x, int y) {
        List<List<Integer>> adj = new ArrayList<>();
        for (int i = 0; i < n; ++i) adj.add(new ArrayList<>());
        for (int i = 0; i < n; ++i) {
            if (i > 0) adj.get(i).add(i - 1);
            if (i + 1 < n) adj.get(i).add(i + 1);
        }
        if (x != y) { adj.get(x-1).add(y-1); adj.get(y-1).add(x-1); }
        int[] res = new int[n];
        for (int s = 0; s < n; ++s) {
            int[] dist = new int[n];
            java.util.Arrays.fill(dist, -1);
            dist[s] = 0;
            java.util.ArrayDeque<Integer> q = new java.util.ArrayDeque<>();
            q.add(s);
            while (!q.isEmpty()) {
                int u = q.poll();
                for (int w : adj.get(u)) if (dist[w] == -1) {
                    dist[w] = dist[u] + 1;
                    ++res[dist[w]];
                    q.add(w);
                }
            }
        }
        return res;
    }
}

