    const adj = Array.from({length: n}, (_, i) => []);
    for (let i = 0; i < n; ++i) {
        if (i > 0) adj[i].push(i - 1);
        if (i + 1 < n) adj[i].push(i + 1);
    }
    if (x !== y) { adj[x-1].push(y-1); adj[y-1].push(x-1); }
    const res = new Array(n).fill(0);
    for (let s = 0; s < n; ++s) {
        const dist = new Array(n).fill(-1);
        dist[s] = 0;
        const q = [s];
        for (let h = 0; h < q.length; ++h) {
            const u = q[h];
            for (const w of adj[u]) if (dist[w] === -1) {
                dist[w] = dist[u] + 1;
                ++res[dist[w]];
                q.push(w);
            }
        }
    }
    return res;
};

