class Solution:
    def countOfPairs(self, n, x, y):
        res = [0] * n
        for a in range(1, n + 1):
            for b in range(1, n + 1):
                if a == b: continue
                d = min(abs(a - b),
                        abs(a - x) + 1 + abs(y - b),
                        abs(a - y) + 1 + abs(x - b))
                res[d - 1] += 1
        return res

